// Regenerates legacy_reference.sql: the database a fresh legacy install
// creates, built by the legacy bootstrap code itself in core.ts order
// (SCHEMA_SQL tables, column healers, indexes, migrationRunner, then the
// lazily applied api_keys column fallbacks), dumped as replayable SQL.
//
// Run from this directory with Node 24+ (node:sqlite, type stripping):
//   node --import ./alias-hooks.mjs generate.mjs
import { DatabaseSync } from "node:sqlite";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const root = new URL("../../../../../", import.meta.url);
const scratch = mkdtempSync(path.join(tmpdir(), "legacy-reference-"));
const file = path.join(scratch, "legacy.sqlite");
const raw = new DatabaseSync(file);

// The better-sqlite3 surface the legacy code uses; nested transactions are savepoints.
let depth = 0;
function transaction(fn, begin) {
  const run = (...args) => {
    const savepoint = depth > 0 ? `sp${depth}` : null;
    raw.exec(savepoint ? `SAVEPOINT ${savepoint}` : begin);
    depth++;
    try {
      const result = fn(...args);
      depth--;
      raw.exec(savepoint ? `RELEASE ${savepoint}` : "COMMIT");
      return result;
    } catch (error) {
      depth--;
      raw.exec(savepoint ? `ROLLBACK TO ${savepoint}; RELEASE ${savepoint}` : "ROLLBACK");
      throw error;
    }
  };
  run.immediate = (...args) => transaction(fn, "BEGIN IMMEDIATE")(...args);
  return run;
}
const db = {
  exec: (sql) => raw.exec(sql),
  prepare: (sql) => raw.prepare(sql),
  pragma: (sql) => raw.prepare(`PRAGMA ${sql}`).all(),
  transaction: (fn) => transaction(fn, "BEGIN"),
  immediate: (fn) => transaction(fn, "BEGIN IMMEDIATE")(),
};

const core = readFileSync(new URL("src/lib/db/core.ts", root), "utf8");
const schema = core.match(/const SCHEMA_SQL = `([\s\S]*?)`;/)[1];
const columns = await import(new URL("src/lib/db/schemaColumns.ts", root).href);
const { runMigrations } = await import(new URL("src/lib/db/migrationRunner.ts", root).href);
const { API_KEY_COLUMN_FALLBACKS } = await import(
  new URL("src/lib/db/apiKeyColumnFallbacks.ts", root).href
);

const statements = schema.split(/;\s*\n/).map((s) => s.trim()).filter(Boolean);
const isIndex = (s) => /^(--[^\n]*\n\s*)*CREATE\s+(UNIQUE\s+)?INDEX/i.test(s);
db.exec(`${statements.filter((s) => !isIndex(s)).join(";\n")};`);
columns.ensureProviderConnectionsColumns(db);
columns.ensureUsageHistoryColumns(db);
columns.ensureCallLogsColumns(db);
db.exec(`${statements.filter(isIndex).join(";\n")};`);
db.exec(`CREATE TABLE IF NOT EXISTS _omniroute_migrations (version TEXT PRIMARY KEY, name TEXT NOT NULL, applied_at TEXT NOT NULL DEFAULT (datetime('now')));
  INSERT OR IGNORE INTO _omniroute_migrations (version, name) VALUES ('001', 'initial_schema');`);
runMigrations(db, { isNewDb: true, databaseExistedBeforeInitialization: false });
columns.ensureUsageHistoryAccountIndex(db);
const keyColumns = new Set(db.prepare("PRAGMA table_info(api_keys)").all().map((c) => c.name));
for (const column of API_KEY_COLUMN_FALLBACKS) {
  if (!keyColumns.has(column.name)) db.exec(`ALTER TABLE api_keys ADD COLUMN ${column.definition}`);
}
// Generation timestamps would make every regeneration differ.
db.exec("UPDATE _omniroute_migrations SET applied_at = '2000-01-01 00:00:00'");

// Dump: schema in creation order (virtual-table shadows skipped), then rows.
const objects = raw
  .prepare(
    "SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' ORDER BY rowid"
  )
  .all();
const virtual = objects
  .filter((o) => o.type === "table" && /^CREATE VIRTUAL TABLE/i.test(o.sql))
  .map((o) => o.name);
const shadow = (name) => virtual.some((v) => name !== v && name.startsWith(`${v}_`));
const quote = (value) => {
  if (value === null || value === undefined) return "NULL";
  if (typeof value === "number" || typeof value === "bigint") return String(value);
  if (value instanceof Uint8Array) return `X'${Buffer.from(value).toString("hex")}'`;
  return `'${String(value).replace(/'/g, "''")}'`;
};
const lines = [
  "-- Legacy red-router reference database: the schema and seeded rows a fresh",
  "-- legacy install creates. Generated by generate.mjs from the legacy bootstrap;",
  "-- regenerate it instead of editing by hand.",
];
const tables = [];
for (const object of objects) {
  if (shadow(object.name)) continue;
  lines.push(`${object.sql};`);
  if (object.type === "table" && !virtual.includes(object.name)) tables.push(object.name);
}
for (const table of tables) {
  for (const row of raw.prepare(`SELECT * FROM "${table.replace(/"/g, '""')}"`).all()) {
    const names = Object.keys(row).map((c) => `"${c}"`).join(",");
    lines.push(`INSERT INTO "${table}" (${names}) VALUES (${Object.values(row).map(quote).join(",")});`);
  }
}
raw.close();
rmSync(scratch, { recursive: true, force: true });
writeFileSync(new URL("legacy_reference.sql", import.meta.url), `${lines.join("\n")}\n`);
console.error(`${objects.length} schema objects, ${tables.length} tables`);
